      "japanese": "<ruby>過去<rt>かこ</rt></ruby>の<ruby>歴史<rt>れきし</rt></ruby>を<ruby>振<rt>ふ</rt></ruby>り<ruby>返<rt>かえ</rt></ruby>り、<ruby>未来<rt>みらい</rt></ruby>を<ruby>迎<rt>むか</rt></ruby>えます。<ruby>今<rt>いま</rt></ruby>この<ruby>瞬間<rt>しゅんかん</rt></ruby>を<ruby>大切<rt>たいせつ</rt></ruby>にして<ruby>前進<rt>ぜんしん</rt></ruby>します。",
      "romaji": "Kako no rekishi o furikaeri, mirai o mukaemasu. Ima kono shunkan o taisetsu ni shite zenshin shimasu.",
